use llm_wiki_desktop_lib::services::import_v2::{connectors::bilibili,media_router::SubtitleKind};
#[test]fn metadata_uses_file_media_router_and_secrets_stay_in_memory(){let (d,p)=bilibili::extract_json(include_str!("../../tests/fixtures/import-v2/web/bilibili/video.json"),"https://www.bilibili.com/video/BV1?spm=secret",false).unwrap();assert_eq!(p.subtitle.unwrap().kind,SubtitleKind::HumanPlatform);assert!(d.subtitle_requests[0].contains("secret"));let persisted=serde_json::to_string(&d).unwrap();assert!(!persisted.contains("secret")&&!persisted.contains("spm"));}
#[test]fn no_subtitle_routes_only_to_authorized_local_asr(){let json=r#"{"code":0,"data":{"title":"v","owner":{"name":"u"},"subtitles":[]}}"#;let (_,without)=bilibili::extract_json(json,"https://bilibili.com/video/BV1",false).unwrap();let (_,with)=bilibili::extract_json(json,"https://bilibili.com/video/BV1",true).unwrap();assert!(!without.requires_asr&&with.requires_asr);}
